// 自毀用的 service worker。
// 舊版網站(Chirpy 主題)在訪客瀏覽器註冊過 /sw.min.js,而且是 cache-first:頁面一旦快取就不再上網抓,
// 改版後這個檔不存在(404),瀏覽器無法更新它,舊訪客會一直看到快取的舊網站。
// 瀏覽器定期(至少每 24 小時)會重抓這個檔;抓到這一版就會安裝、清掉所有快取、註銷自己,並重新載入頁面。
// 新網站沒有 service worker,這個檔留著就好,不要刪。
self.addEventListener('install', () => self.skipWaiting());
self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.map((k) => caches.delete(k)));
    await self.registration.unregister();
    const windows = await self.clients.matchAll({ type: 'window' });
    windows.forEach((w) => w.navigate(w.url));
  })());
});
